export function getLocalizedContent(locale: string): LocalizedContent {
  const row=rows[locale]; if(!row) return en;
  const faqLabels=localizedFaqLabels[locale]||[row[1],row[3]];
  return {researchSnapshot:row[0],faqTitle:faqLabels[0],faqIntro:row[2],allFaq:faqLabels[1],guide:row[4],researchBasis:row[5],scopeTitle:row[6],scopeText:row[7],open:row[8],close:row[9],factCheckedHelp:row[10],categories:row[11].split("|")};
}

