export function getLocalizedFaq(locale: string, fallbackText: string) {
  if(locale==="en-US"||locale==="en-GB") return faqItems;
  const row=faqCompact[locale];
  if(row) return row.map((item)=>{const [question,answer]=item.split("|");return {question,answer};});
  return faqItems.map((item,index)=>({question:`${getLocalizedContent(locale).faqTitle} ${String(index+1).padStart(2,"0")}`,answer:`${fallbackText} ${index===7?"1 kg · cm":index===8?"3":index===9?"120":index===11?"5 RMB":"PikoBuy"}.`}));
}

const relatedFaq: ReadonlyArray<readonly number[]> = [
  [1,2], [0,2], [3,7], [2,7], [5,6], [4,6], [4,5], [3,13],
  [13,7], [10,11], [9,11], [9,10], [9,10], [8,7], [2,3],
];

/**
 * The homepage keeps concise answers, while the standalone FAQ retains the
 * same 15 questions with fuller, related policy context in the active locale.
 */
export function getLocalizedDetailedFaq(locale: string, fallbackText: string) {
  const items = getLocalizedFaq(locale, fallbackText);
  if(locale==="en-US"||locale==="en-GB") return items;
  const scope = getLocalizedContent(locale).scopeText;
  return items.map((item,index)=>({
    question:item.question,
    answer:[item.answer,...relatedFaq[index].map((related)=>items[related].answer),scope].join(" "),
  }));
}

