export type LocalizedSeoSection = {
  slot: string;
  heading: string;
  paragraphs: readonly string[];
};

/**
 * Return the same seven semantic content slots as the English master article.
 * Related facts add the long-form context without borrowing the next section,
 * which previously made a language switch produce a different article.
 */
export function getLocalizedSeoSections(locale: string, slug: string, fallbackText: string): readonly LocalizedSeoSection[] {
  const items=getLocalizedFaq(locale,fallbackText);
  const localized=getLocalizedContent(locale);
  const scope=localized.scopeText;
  const shipping=getShippingCopy(locale);
  const plans=articleSectionPlans[slug]||articleSectionPlans["how-pikobuy-works"];
  const headings:Record<string,readonly string[]>={
    "how-pikobuy-works":[items[1].question,items[2].question,items[4].question,items[9].question,shipping.inputsTitle,shipping.riskTitle,items[8].question],
    "pikobuy-shipping-cost-guide":[shipping.title,shipping.inputsTitle,shipping.calloutTitle,`${shipping.inputs[1].label}: ${shipping.inputs[1].description}`,shipping.riskTitle,items[9].question,`${shipping.inputs[4].label}: ${shipping.calloutBody}`],
    "pikobuy-qc-photo-checklist":[items[4].question,`${items[0].question} ${items[4].question}`,`${localized.categories.join(" · ")}`,items[6].question,items[5].question,items[9].question,`${items[13].question} ${items[8].question}`],
    "pikobuy-restricted-items-guide":[shipping.riskTitle,shipping.inputsTitle,`${localized.categories[10]} · ${shipping.inputs[1].label}`,shipping.calloutTitle,items[13].question,shipping.title,`${items[4].question} ${items[9].question}`],
    "pikobuy-spain-guide":[`${items[0].question} · España`,shipping.title,`${shipping.inputsTitle} · España`,`${shipping.riskTitle} · España`,items[4].question,items[8].question,`${shipping.calloutTitle} · España`],
    "pikobuy-usa-guide":[`${items[0].question} · USA`,shipping.title,`${shipping.inputsTitle} · USA`,`${shipping.riskTitle} · USA`,items[13].question,items[4].question,`${shipping.calloutTitle} · USA`],
  };
  const sectionHeadings=headings[slug]||headings["how-pikobuy-works"];
  return plans.map((plan,position)=>{
    const contextualParagraph=(indexes:readonly number[])=>indexes.map((index)=>{
      const context=[items[index].answer,...relatedFaq[index].map((related)=>items[related].answer)];
      return `${items[index].question} ${context.join(" ")}`;
    }).join(" ");
    const split=Math.max(1,Math.ceil(plan.facts.length/2));
    const firstFacts=plan.facts.slice(0,split);
    const secondFacts=plan.facts.slice(split);
    const shippingSupport=[
      `${shipping.intro} ${shipping.calloutBody}`,
      shipping.inputs.map((input)=>`${input.label}: ${input.description}`).join(" "),
      `${shipping.sampleBody} ${shipping.riskBody}`,
    ];
    return {
      slot:`${slug}:${position+1}`,
      heading:sectionHeadings[position]||items[plan.heading].question,
      paragraphs:[
        contextualParagraph(firstFacts),
        contextualParagraph(secondFacts.length?secondFacts:firstFacts),
        `${shippingSupport[position%shippingSupport.length]} ${fallbackText} ${scope}`,
      ],
    };
  });
}
